const int xAxis = A1;//宣告輸入腳位 
const int yAxis = A2; 
int responseDelay = 2; 
void setup() { 
 Mouse.begin(); 
} 
void loop() { 
 int xAxis = analogRead(xAxis);//讀取彎曲率感知器數值 
 int yAxis = analogRead(yAxis); 

 delay(500); 
 xAxis=map(xAxis,400,500,0,1023);//轉換成x 與y 軸的數值 
 yAxis=map(yAxis,400,500,0,1023); 
} 
void setup(){ 
 Serial.begin(9600); 
 pinMode(2,INPUT); 
 pinMode(3,INPUT); 
 Mouse.begin(); 
} 
void loop(){ 
 int fsr_value1 = analogRead(A0); // 讀取FSR 值 
 int fsr_value2 = analogRead(A1); // 讀取FSR 值 
 if(fsr_value1 > 100){ 
 Mouse.press(MOUSE_LEFT); 
 }else 
 { Mouse.release(MOUSE_LEFT); } 
 if(fsr_value2 > 100){ 
 Mouse.press(MOUSE_RIGHT); 
 }else 
 { Mouse.release(MOUSE_RIGHT); } 
} 

五、實驗五： 
為了設計出更能夠配合彎曲率感知器的使用模式，我們決定採用氣球去當作彎曲率感知器的依附對象，捏擠氣球便能改變其形狀，讓彎曲率感知器也能夠跟著改變阻值，氣球方便放置任何部位，同時也解決利用方盒放置臉部不便移動滑鼠的問題，透過擠壓球體來操作滑鼠的設計也可以應用在多種肢體障礙者的應用場合。 
經過實驗後我們發現，氣球雖然有機動性高的優勢，但也有先天上的缺陷，例如因為消氣而導致電阻值變化的漂移，以及過度擠壓或被感測元件的銳角戳破而爆裂。 



